-- Training Target - Viewpoint models: registers the model manifest of the Training
-- Target tiles with Project Viewpoint (Viewpoint.ModelPacks.register(modId, path),
-- path relative to this mod). Does nothing when Viewpoint is not active. The models
-- and the manifest are generated by source/viewpoint/export_viewpoint.py.
local MOD_ID = "batman_TrainingTargetViewpoint"
local MANIFEST = "media/training-viewpoint/training.properties"

local registered = false

local function register()
    if registered or not Viewpoint or not Viewpoint.ModelPacks then return end
    local ok, res = pcall(Viewpoint.ModelPacks.register, MOD_ID, MANIFEST)
    if ok and res then
        registered = true
    elseif not ok then
        print("[TrainingTargetViewpoint] registration failed: " .. tostring(res))
    end
end

Events.OnGameBoot.Add(register)
Events.OnGameStart.Add(register)
register()
